const leagueRankingActive=(level:number)=>{const leagues:[[number,number|undefined],...Array<[number,number|undefined]>]=[[1,50],[51,100],[101,150],[151,200],[201,250],[251,350],[351,500],[501,700],[701,1000],[1001,undefined]];const [start,end]=[...leagues].reverse().find(([entry])=>level>=entry)??[1,50];const offset=level-start;const competitionStart=start+Math.floor(offset/30)*30+10;const competitionEnd=end===undefined?competitionStart+19:Math.min(competitionStart+19,end);return level>=competitionStart&&level<=competitionEnd}
const leagueTitle=(level:number)=>level<=50?'BRONZE LEAGUE':level<=100?'SILVER LEAGUE':level<=150?'GOLD LEAGUE':level<=200?'PLATINUM LEAGUE':level<=250?'DIAMOND LEAGUE':level<=350?'ELITE LEAGUE':level<=500?'MASTER LEAGUE':level<=700?'GRANDMASTER LEAGUE':level<=1000?'LEGEND LEAGUE':'MYTHIC LEAGUE'
